const rows = $input.all().map((item) => item.json || {}).filter((row) => row.enabled !== false && !String(row.case_id || '').startsWith('pro_v3_'));
const SOURCE_HASH = '0ba97ce90f4b62d21f15492f54ada491eaa63773d0bd34ee6ca1448752aca857';
const LEGACY_SOURCE_HASH = '27b0dfe58c248c2a914ba01fc7ca5d299c2cc281965dd9c33f00279b6e7659c3';
const COMPAT_SOURCE_HASHES = new Set([SOURCE_HASH]);
const SUITE_VERSION = '3.0.3';
const forbiddenEventFields = ['body','message_text','history','email','phone','name','conversation_summary','raw_error','full_prompt','full_reply'];
const hash = (value) => {
  let h = 2166136261;
  for (const ch of String(value || '')) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
};
const parseJson = (value, label, failures) => {
