};
const hasExpected = (expected, key) => Array.isArray(expected[key]) && expected[key].length > 0;
const hasText = (expected, key, matcher) => hasExpected(expected, key) && expected[key].some((value) => matcher.test(String(value)));
const runCase = (row) => {
  const failures = [];
  let output = '';
  let summary = '';
