const SOURCE_HASH = '0ba97ce90f4b62d21f15492f54ada491eaa63773d0bd34ee6ca1448752aca857';
const SUITE_VERSION = '3.0.3';
const interpretV3 = (function(){ const module={exports:{}}; const exports=module.exports;
'use strict';

const SOLUTIONS = new Set(['web_catalogo', 'chatbot_whatsapp_ia', 'pack_web_chatbot', 'asesor']);

function clean(value) {
  return String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
}

function normalized(value) {
  return clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

function pickMatch(text, expressions) {
  for (const expression of expressions) {
    const match = text.match(expression);
